sys_script_include.script:
var ScheduleUtils = Class.create();
ScheduleUtils.prototype = {
    initialize: function() {},

    getAvailableSchedules: function(scheduleId) {
        var userId = gs.getUserID();
        var available = [];

        var grSchedule = new GlideRecord("x_1793782_traini_0_schedule");
        if (scheduleId) {
            grSchedule.addQuery("sys_id", scheduleId); 
        }
        grSchedule.query();

        while (grSchedule.next()) {
            var courseId        = grSchedule.course.toString();
            var instructorId    = grSchedule.getValue('instructor') || '';
            var trainingDateStr = grSchedule.getValue('training_date');
            var maxVacancies    = grSchedule.max_vacancies.nil() ? 0 : parseInt(grSchedule.max_vacancies, 10);

            // Instrutor não pode se matricular
            if (instructorId === userId) {
                if (scheduleId) return 'instructor';
                continue;
            }

            // Já matriculado nesta agenda 
            var dup = new GlideRecord('x_1793782_traini_0_enrollment');
            dup.addQuery('requester', userId);
            dup.addQuery('schedule', grSchedule.sys_id);
            dup.addQuery('state', 'IN', '1,3');
            dup.query();
            if (dup.hasNext()) {
                if (scheduleId) return 'duplicate';
                continue;
            }

            // Máximo 3 matrículas no mesmo curso
            var count = new GlideAggregate('x_1793782_traini_0_enrollment');
            count.addQuery('requester', userId);
            count.addQuery('schedule.course', courseId);
            count.addQuery('state', 'IN', '1,3');
            count.addAggregate('COUNT');
            count.query();
            if (count.next() && parseInt(count.getAggregate('COUNT'), 10) >= 3) {
                if (scheduleId) return 'course_limit';
                continue;
            }

            // Agenda cheia
            if (maxVacancies > 0) {
                var occ = new GlideAggregate('x_1793782_traini_0_enrollment');
                occ.addQuery('schedule', grSchedule.sys_id);
                occ.addQuery('state', 'IN', '1,3');
                occ.addAggregate('COUNT');
                occ.query();
                if (occ.next() && parseInt(occ.getAggregate('COUNT'), 10) >= maxVacancies) {
                    if (scheduleId) return 'no_seats';
                    continue;
                }
            }

            // Até um dia antes do treinamento
            if (trainingDateStr) {
                var trainingDate = new GlideDateTime(trainingDateStr);
                var today = new GlideDateTime();
                trainingDate.addDaysUTC(-1);

                if (today.after(trainingDate)) {
                    if (scheduleId) return 'deadline';
                    continue;
                }
            }

            // Agenda liberada
            if (scheduleId)
                return 'true';
            available.push(grSchedule.getUniqueValue());
        }

        return available.join(",");
    },

    type: 'ScheduleUtils'
};
